CREATE TABLE cmdb_ire_quality_findings (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT UNSIGNED NOT NULL, rule_key VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, severity ENUM('INFO','WARNING','ERROR') NOT NULL, ci_id BIGINT UNSIGNED NOT NULL, field_key VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '', details JSON NOT NULL, state ENUM('OPEN','RESOLVED') NOT NULL DEFAULT 'OPEN', detected_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), checked_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), resolved_at DATETIME(6) NULL, UNIQUE KEY cmdb_ire_finding_key(tenant_id,rule_key,ci_id,field_key), KEY cmdb_ire_finding_queue(tenant_id,state,severity,id), KEY cmdb_ire_finding_ci(tenant_id,ci_id,state), CONSTRAINT cmdb_ire_finding_ci FOREIGN KEY(tenant_id,ci_id) REFERENCES cmdb_cis(tenant_id,id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
